(function(){
  function createTurn(book, options = {}) {
    const pages = Array.from(book.children);
    let index = 0;
    const handlers = { turning: [] };

    const emitTurning = () => {
      const page = index + 1;
      const view = [page, page + 1 <= pages.length ? page + 1 : 0];
      if (options.when && typeof options.when.turning === 'function') {
        options.when.turning(null, page, view);
      }
      handlers.turning.forEach((fn) => fn({ page, view }));
    };

    const render = () => {
      pages.forEach((p, i) => {
        const inView = i === index || i === index + 1;
        p.style.display = inView ? 'block' : 'none';
      });
      emitTurning();
    };

    const api = {
      turn(direction) {
        if (direction === 'next' && index + 2 < pages.length) index += 2;
        if (direction === 'previous' && index - 2 >= 0) index -= 2;
        render();
      },
      on(event, handler) {
        if (handlers[event]) handlers[event].push(handler);
      }
    };

    book.style.display = 'flex';
    book.style.gap = '0';
    pages.forEach((p) => { p.style.width = '50%'; p.style.height = '100%'; });
    render();
    return api;
  }

  window.createTurn = createTurn;
})();
